高精度减法
big sub(big x,big y){
    big z;
    if(!cmp(x,y)){
        swap(x,y);
        z.flag=0;
    }
    z.size=max(x.size,y.size);
    int temp=0;
    for(int i=0;i<z.size;i++){
        z.num[i]=x.num[i]-temp-y.num[i]+10;
        temp=(z.num[i]<10);
        z.num[i]%=10;
    }
    clean(z);
    return z;
}

