问：给n个数，选任意个异或，最大值和最小值(非零)是多少？
int n,x,b[64];
void insert(int x){
    for(int i=62;i>=0;i--){
        if(!(x>>i&1)) continue;
        if(!b[i]){
            b[i]=x;
            break;
        }
        x^=b[i];
    }
}
int getMax(){ 最大异或值
    int ans=0;
    for(int i=62;i>=0;i--){
        if((ans^b[i])>ans) ans^=b[i];
    }
    return ans;
}
int getMin(){ 最小异或值
    for(int i=0;i<=62;i++){
        if(b[i]){
            int res=b[i];
            for(int j=i-1;j>=0;j--){
                if(b[j]&&(res&(1LL<<j))) res^=b[j];
            }
            return res;
        }
    }
    return 0;
}

